from test_bufftap import test, tests
test('Combat probe arms, records in combat and reports after',"local B=BuffTap; local out={}; local p=B.Print; B.Print=function(m) out[#out+1]=m end; B:ArmCombatProbe(); local f=B.combatProbeFrame; local h=f.scripts.OnEvent; InCombatLockdown=function() return true end; h(f,'PLAYER_REGEN_DISABLED'); h(f,'UNIT_AURA','player'); InCombatLockdown=function() return false end; h(f,'PLAYER_REGEN_ENABLED'); B.Print=p; local all=table.concat(out,'\\n'); assert(all:find('Combat probe results',1,true) and all:find('buff change in combat',1,true), all); assert(not B.combatProbe.armed)")
